style.css:
/* Этот код будет применяться ко всем элементам body на youtube.com */
body {
    overflow-x: hidden !important;
}

/* Этот код будет применяться ко всем элементам ytd-app на youtube.com */
ytd-app {
    overflow-x: hidden !important;
}

/* Если 'прокрутка' - это АТРИБУТ (например, <ytd-app прокрутка>), то вот так: */
ytd-app[прокрутка] {
    overflow-x: hidden !important;
}
